-- Переводы строк, появившихся в 6.2.6 - 6.2.13 (добавляются в ruRU.lua через tools/ru/sync_ui.py --add).
  ["Hold Ctrl and drag a window with the right mouse button to change its size."] = "Зажмите Ctrl и перетащите окно правой кнопкой мыши, чтобы изменить его размер.",
  ["Black"] = "Черный",
  ["Logo size"] = "Размер логотипа",
  ["How large the OneForAll minimap button is."] = "Размер кнопки OneForAll у миникарты.",
  ["60 - 150 %. Mouse wheel or drag."] = "60 - 150 %. Колесико мыши или перетаскивание.",
  ["Alt + right-click"] = "Alt + правый щелчок",
  ["Ctrl + right-click"] = "Ctrl + правый щелчок",
  ["Alt + left-click"] = "Alt + левый щелчок",
  ["Ctrl + Alt + right-click"] = "Ctrl + Alt + правый щелчок",
  ["Shift + Alt + right-click"] = "Shift + Alt + правый щелчок",
  ["On your junk list (%s to take it off)"] = "В вашем списке хлама (%s, чтобы убрать)",
  ["Also the items on your own junk list: click an item in your bags with the junk list key (default Alt + right-click) to put it on the list or take it off. Hold Shift at the merchant to skip."] = "А также предметы из вашего списка хлама: щелкните по предмету в сумках клавишей списка хлама (по умолчанию Alt + правый щелчок), чтобы добавить или убрать его. Удерживайте Shift у торговца, чтобы пропустить.",
  ["Junk list key"] = "Клавиша списка хлама",
  ["The click that puts an item in your bags on the junk list."] = "Сочетание для добавления предмета в сумках в список хлама.",
  ["Choose another one when an addon of yours uses Alt + right-click on bag items. Clicking again takes the item off the list."] = "Выберите другое сочетание, если другой ваш аддон использует Alt + правый щелчок по предметам в сумках. Повторное нажатие убирает предмет из списка.",
  ["Items you added with the junk list key in your bags."] = "Предметы, добавленные вами клавишей списка хлама в сумках.",
  ["Nothing on the list. Click an item in your bags with the junk list key (default Alt + right-click) to add it - Sell junk then sells it at merchants."] = "Список пуст. Щелкните по предмету в сумках клавишей списка хлама (по умолчанию Alt + правый щелчок), чтобы добавить его — тогда «Продавать хлам» будет продавать его торговцам.",
  ["Bags, windows, the minimap and other helpers for the game's interface."] = "Сумки, окна, миникарта и другие помощники интерфейса игры.",
  ["Group invites, duels and recipe sharing."] = "Приглашения в группу, дуэли и обмен рецептами.",
  ["Hold Ctrl and the right mouse button on a window like the character or quest log window and drag: right or down makes it larger, left or up smaller (50 - 150 %). The size shows at the cursor and is remembered."] = "Зажмите Ctrl и правую кнопку мыши на окне (например, окне персонажа или журнале заданий) и потяните: вправо или вниз — увеличить, влево или вверх — уменьшить (50 - 150 %). Размер виден у курсора и запоминается.",
  ["The game's loot glow. Quest givers and some other NPCs glow too - that comes with this game setting. Changes only this one setting - your outline settings stay as they are. After switching it off, restart the game."] = "Игровое свечение добычи. Квестодатели и некоторые другие NPC тоже светятся — это особенность настройки игры. Меняет только этот параметр — настройки контура остаются прежними. После выключения перезапустите игру.",
  ["Drag the mark to where you want it on the nameplate."] = "Перетащите метку туда, где она должна быть на индикаторе здоровья.",
  ["Low level quests (grey)"] = "Задания низкого уровня (серые)",
  ["Also a grey ! for quests that are grey for you."] = "Также серый ! для заданий, которые для вас серые.",
  ["They give little or no experience. Needs \"Quest icons\"."] = "Они дают мало или совсем не дают опыта. Требуются \"Значки заданий\".",
  ["Hide walking routes"] = "Скрывать маршруты ходьбы",
  ["No yellow lines where quest givers walk around."] = "Без желтых линий там, где ходят квестодатели.",
  ["The icon of a walking quest giver stays; it shows where the giver is in the quest data. Needs \"Quest icons\"."] = "Значок ходящего квестодателя остается; он показывает место по базе заданий. Требуются \"Значки заданий\".",
  ["This loot is not worth more than anything in your bags."] = "Эта добыча стоит не дороже всего, что лежит в ваших сумках.",
  ["Everything in your bags is worth as much or more."] = "Все в ваших сумках стоит столько же или дороже.",
  ["With the controller the map is not switched from OneForAll (it would block the controller) - pick the zone on the map yourself."] = "С контроллером OneForAll не переключает карту (иначе это заблокирует управление) — выберите зону на карте вручную.",
